import { citypeList, saveAllCitype } from "@/api/system/ciModel";
import { Message } from 'element-ui';
import draggable from 'vuedraggable';
export default {
  components: {
    draggable: draggable
  },
  props: ['isShow'],
  data: function data() {
    return {
      dragOptions: {
        animation: 150,
        scroll: true,
        group: 'description',
        disabled: false,
        ghostClass: 'ghost'
      },
      ciTypeList: [],
      saveLoading: false
    };
  },
  mounted: function mounted() {
    // console.log(draggable)
    this.getAllCitype();
  },
  methods: {
    // 获得全部层级
    getAllCitype: function getAllCitype() {
      var _this = this;
      citypeList().then(function (res) {
        _this.ciTypeList = res.Return;
      });
    },
    // 移除层级
    removeCiType: function removeCiType(ciType) {
      this.$set(ciType, 'isDeleted', true);
    },
    // 恢复层级
    recoverCiType: function recoverCiType(ciType) {
      this.$set(ciType, 'isDeleted', null);
    },
    // 保存结果
    save: function save() {
      var _this2 = this;
      this.saveLoading = true;
      saveAllCitype({
        ciTypeList: this.ciTypeList
      }).then(function (res) {
        _this2.saveLoading = false;
        Message({
          type: 'success',
          message: '保存成功!'
        });
        _this2.$emit("saveCitypeManage");
      }).catch(function () {
        _this2.saveLoading = false;
      });
    }
  }
};
